package org.dmg.balletmaster.loki

import org.junit.jupiter.api.Assertions.*
import org.junit.jupiter.api.Test
import java.time.Instant

/**
 * Real integration test executing against a real Grafana Loki engine.
 *
 * Verifies that:
 * 1. LogQL expressions generated by [LogQlQueryBuilder] are valid LogQL and accepted by real Loki.
 * 2. Exact `operationId` filtering works on real Loki: a query for 'ord-1' strictly filters out
 *    distractor events carrying 'ord-100', even though both match the substring filter `|= "ord-1"`.
 * 3. Log stream parsing and normalization in [LokiQueryClient] and [LokiLogParser] reconstruct
 *    accurate [LokiLogObservation] instances from real Loki query responses.
 * 4. Scope filtering ([LogScope.SDK_ONLY] vs [LogScope.ALL_CORRELATED]) behaves correctly on real Loki.
 */
class LokiRealQueryIntegrationTest {

    @Test
    fun realLokiExecutesLogQlAndEnforcesExactOperationIdFiltering() {
        val lokiBaseUrl = RealLokiTestCluster.getOrStartLoki()
        val client = LokiQueryClient(LokiClientConfig(baseUrl = lokiBaseUrl))

        val app = "order-service"
        val env = "test"
        val uniqueSuffix = System.currentTimeMillis()
        val targetOpId = "ord-target-$uniqueSuffix"
        val distractorOpId = "ord-target-${uniqueSuffix}00" // Substring matches "ord-target-$uniqueSuffix"

        val now = Instant.now()
        val baseTsNs = (now.toEpochMilli() - 10_000) * 1_000_000L

        // 1. Prepare target operation events (ord-target-...)
        val targetLines = listOf(
            baseTsNs + 10_000_000L to """{"timestamp":"${now.minusSeconds(9)}","logger_name":"org.dmg.balletmaster.step","level":"INFO","message":"step.exception","ballet_operation":"orderFlow","ballet_operationId":"$targetOpId","ballet_attempt":0,"ballet_suffix":"","ballet_step":"CHARGE_CARD","phase":"map","exception":"IllegalArgumentException"}""",
            baseTsNs + 20_000_000L to """{"timestamp":"${now.minusSeconds(8)}","logger_name":"org.dmg.balletmaster.step","level":"INFO","message":"chain.stopped","ballet_operation":"orderFlow","ballet_operationId":"$targetOpId","ballet_attempt":0,"ballet_suffix":"","ballet_step":"CHARGE_CARD","outcome":"FAILURE","executedSteps":1,"totalSteps":2,"durationMs":24}"""
        )

        // 2. Prepare distractor operation events on SAME (app, env) stream with prefix collision (ord-target-...00)
        val distractorLines = listOf(
            baseTsNs + 30_000_000L to """{"timestamp":"${now.minusSeconds(7)}","logger_name":"org.dmg.balletmaster.lock","level":"INFO","message":"lock.blocked","ballet_operation":"orderFlow","ballet_operationId":"$distractorOpId","ballet_attempt":0,"ballet_suffix":"","ballet_step":"CHARGE_CARD","status":"BLOCKED","leaseMs":20,"waitMs":24,"attempts":1}""",
            baseTsNs + 40_000_000L to """{"timestamp":"${now.minusSeconds(6)}","logger_name":"org.dmg.balletmaster.step","level":"INFO","message":"chain.stopped","ballet_operation":"orderFlow","ballet_operationId":"$distractorOpId","ballet_attempt":0,"ballet_suffix":"","ballet_step":"CHARGE_CARD","outcome":"STATE","status":"BLOCKED","durationMs":25}"""
        )

        // 3. Prepare application host log (non-SDK logger) carrying correlated targetOpId in MDC
        val hostAppLines = listOf(
            baseTsNs + 50_000_000L to """{"timestamp":"${now.minusSeconds(5)}","logger_name":"com.example.orders.PaymentClient","level":"WARN","message":"Payment gateway rejected card limit","mdc":{"operationId":"$targetOpId","userId":"usr-999"}}"""
        )

        // Push all to real Loki
        val streamLabels = mapOf("app" to app, "environment" to env)
        RealLokiTestCluster.pushLogs(lokiBaseUrl, streamLabels, targetLines + distractorLines + hostAppLines)

        val windowStart = now.minusSeconds(60)
        val windowEnd = now.plusSeconds(30)

        // 4. Query target operation with SDK_ONLY scope
        val sdkQuery = LogQlQueryBuilder.build(app, env, targetOpId, scope = LogScope.SDK_ONLY)
        val sdkResult = RealLokiTestCluster.waitForQuery(
            client = client,
            query = sdkQuery,
            start = windowStart,
            end = windowEnd,
            expectedMinEntries = 2
        )

        assertEquals(Completeness.COMPLETE, sdkResult.completeness)
        // Must find strictly the 2 target SDK events:
        assertEquals(2, sdkResult.observations.size, "Expected exactly 2 target events, got ${sdkResult.observations.map { it.rawLine }}")
        assertTrue(sdkResult.observations.all { it.correlation?.operationId == targetOpId })
        assertFalse(sdkResult.observations.any { it.correlation?.operationId == distractorOpId })

        // Validate observation fields normalized from real Loki response
        val exObs = sdkResult.observations.first { it.event == "step.exception" }
        assertEquals("step.exception", exObs.event)
        assertEquals("INFO", exObs.level)
        assertEquals("orderFlow", exObs.correlation?.operation)
        assertEquals(targetOpId, exObs.correlation?.operationId)
        assertEquals("CHARGE_CARD", exObs.correlation?.step)
        assertEquals(0, exObs.correlation?.attempt)
        assertEquals("", exObs.correlation?.suffix)
        assertEquals("map", exObs.attributes["phase"])
        assertEquals("IllegalArgumentException", exObs.attributes["exception"])

        val stopObs = sdkResult.observations.first { it.event == "chain.stopped" }
        assertEquals("chain.stopped", stopObs.event)
        assertEquals("INFO", stopObs.level)
        assertEquals("FAILURE", stopObs.attributes["outcome"])
        assertEquals(1, stopObs.attributes["executedSteps"])
        assertEquals(2, stopObs.attributes["totalSteps"])

        // 5. Query target operation with ALL_CORRELATED scope
        val correlatedQuery = LogQlQueryBuilder.build(app, env, targetOpId, scope = LogScope.ALL_CORRELATED)
        val correlatedResult = RealLokiTestCluster.waitForQuery(
            client = client,
            query = correlatedQuery,
            start = windowStart,
            end = windowEnd,
            expectedMinEntries = 3
        )

        assertEquals(Completeness.COMPLETE, correlatedResult.completeness)
        assertEquals(3, correlatedResult.observations.size)
        assertTrue(correlatedResult.observations.any { it.logger == "com.example.orders.PaymentClient" })
        assertFalse(correlatedResult.observations.any { it.correlation?.operationId == distractorOpId })

        // 6. Query distractor operation directly and verify its isolation
        val distractorQuery = LogQlQueryBuilder.build(app, env, distractorOpId, scope = LogScope.SDK_ONLY)
        val distractorResult = RealLokiTestCluster.waitForQuery(
            client = client,
            query = distractorQuery,
            start = windowStart,
            end = windowEnd,
            expectedMinEntries = 2
        )

        assertEquals(2, distractorResult.observations.size)
        assertTrue(distractorResult.observations.all { it.correlation?.operationId == distractorOpId })
        assertFalse(distractorResult.observations.any { it.correlation?.operationId == targetOpId })
    }
}
